"""Build static EV listings and model pages from the verified catalogue."""
from pathlib import Path
from html import escape as esc
import json,re,hashlib
from components import road_widget,running_widget,subsidy
root=Path(__file__).resolve().parents[1];dist=root/'dist'
models=json.loads((root/'vehicle-catalogue.json').read_text())
# Retain distinct photographs even when a source exposes the same file at two URLs.
for model in models:
 seen=set();photos=[]
 for photo in model['images']:
  digest=hashlib.sha256((dist/photo['path'].lstrip('/')).read_bytes()).hexdigest()
  if digest not in seen:photos.append(photo);seen.add(digest)
 model['images']=photos
 if len(photos)<2:raise ValueError('At least two distinct photos required: '+model['slug'])
(root/'vehicle-catalogue.json').write_text(json.dumps(models,ensure_ascii=False,indent=2))
e=lambda x:esc(str(x),quote=True)
priority={'Tata':0,'Mahindra':1,'Maruti Suzuki':2,'MG':3,'Hyundai':4}
models.sort(key=lambda v:(v['type']!='car',priority.get(v['brand'],10),v['brand'].lower(),v['priceMin'] or 1e10,v['name'].lower()))
base=(dist/'explore-evs/index.html').read_text()
header=re.search(r'<header>.*?</header>',base,re.S).group()
footer=re.search(r'<footer>.*?</footer>',base,re.S).group()
price=road_widget()
schemes=re.search(r'<section id="schemes".*?</section>',base,re.S).group()
def shell(title,description,body,extra=''):
 return '<!doctype html><html lang="en"><head><script src="/navigation.js?v=6"></script><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+e(title)+' — Renew India</title><meta name="description" content="'+e(description)+'"><link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/catalogue.css"><link rel="stylesheet" href="/improvements.css?v=7"></head><body><a class="skip" href="#main" target="_self">Skip to content</a>'+header+'<main id="main">'+body+'</main>'+footer+extra+'</body></html>'
def link(url,text,cls=''):return '<a target="_self" href="'+e(url)+'"'+(' class="'+cls+'"' if cls else '')+'>'+text+'</a>'
def type_name(v):return {'car':'Electric car','scooter':'Electric scooter','motorcycle':'Electric motorcycle','three-wheeler':'Electric auto-rickshaw'}[v['type']]
def card(v):
 img=v['images'][0];url='/explore-evs/'+v['slug']+'/'
 return '<article class="ev-card" data-price="'+e(v.get('priceMin') or '')+'" data-slug="'+e(v['slug'])+'" data-type="'+e(v['type'])+'" data-brand="'+e(v['brand'])+'" data-name="'+e(v['name'])+'"><a class="ev-card-link" href="'+url+'" target="_self"><div class="ev-card-photo"><img src="'+e(img['path'])+'" alt="'+e(img['alt'])+'" loading="lazy" width="720" height="450"><span>'+e(v.get('body',type_name(v)))+'</span></div><div class="ev-card-body"><span class="maker">'+e(v['brand'])+'</span><h2>'+e(v['name'])+'</h2><dl class="ev-card-specs"><div><dt>Claimed range</dt><dd>'+e(v['range'])+'</dd></div><div><dt>Battery</dt><dd>'+e(v['battery'])+'</dd></div></dl><p class="ev-card-price">'+e(v['price'])+'</p><p class="ev-price-note">'+e(v.get('priceNote','Ex-showroom estimate; confirm local quote.'))+'</p><span class="ev-card-action">Explore model <span aria-hidden="true">→</span></span></div></a><label class="ev-compare"><input type="checkbox" data-compare="'+e(v['slug'])+'"> Add to comparison</label></article>'

def variant_table(v):
 variants=v.get('variants',[])
 if not variants:return ''
 return '<section class="model-variants"><details><summary>Compare battery and range by variant ('+str(len(variants))+')</summary><p class="micro">Source-listed specifications. Range cycles may differ; this is not a real-world range test.</p><div class="variant-table-wrap"><table><thead><tr><th>Variant</th><th>Battery</th><th>Listed range</th></tr></thead><tbody>'+''.join('<tr><th>'+e(x['name'])+'</th><td>'+e(x['battery'])+'</td><td>'+e(x['range'])+'</td></tr>' for x in variants)+'</tbody></table></div></details></section>'

brands=sorted(set(v['brand'] for v in models))
intro='<div class="breadcrumbs">'+link('/','Home')+'<span>/</span><span>Explore EVs</span></div><section id="explore" class="section ev-catalogue"><div class="section-head"><div><span class="eyebrow">THE ELECTRIC SHIFT</span><h1 class="section-title">Find your next<br>electric chapter.</h1></div><p>Real model photos. Details worth comparing.<br>Explore cars, scooters, motorcycles and electric autos in India.</p></div><nav class="section-links"><a href="#running-cost" target="_self">Running-cost savings ↓</a><a href="#price" target="_self">On-road price estimate ↓</a><a href="#schemes" target="_self">EV support ↓</a></nav><div class="ev-toolbar"><div class="tabs" aria-label="Vehicle category"><button type="button" data-ev-type="all" class="active" aria-pressed="true">All vehicles</button><button type="button" data-ev-type="car" aria-pressed="false">Electric cars</button><button type="button" data-ev-type="two-wheeler" aria-pressed="false">Two-wheelers</button><button type="button" data-ev-type="three-wheeler" aria-pressed="false">Electric autos</button></div><label class="search"><span aria-hidden="true">⌕</span><input id="ev-search" type="search" placeholder="Search brand or model" aria-label="Search vehicles"></label><label class="ev-brand-label">Brand <select id="ev-brand"><option value="all">All brands</option>'+''.join('<option>'+e(b)+'</option>' for b in brands)+'</select></label><label class="ev-budget-label">Maximum budget <select id="ev-budget"><option value="all">Any budget</option><option value="100000">Up to ₹1 lakh</option><option value="200000">Up to ₹2 lakh</option><option value="500000">Up to ₹5 lakh</option><option value="1000000">Up to ₹10 lakh</option><option value="1500000">Up to ₹15 lakh</option><option value="2000000">Up to ₹20 lakh</option><option value="3000000">Up to ₹30 lakh</option><option value="5000000">Up to ₹50 lakh</option></select></label><button type="button" class="ev-reset" id="ev-reset">Reset filters</button></div><div class="ev-catalogue-meta"><p id="ev-count" role="status">'+str(len(models))+' models</p><span>Manufacturer / CarWale / BikeWale listings · Checked 14 October 2026</span></div><p class="micro ev-range-note">Budget filters use the lowest listed ex-showroom variant price, not an on-road total. Battery-rental and subsidy conditions may apply; read each price note. Ranges reported by the source are not guaranteed real-world distance; test cycles can differ. Battery, features and price depend on the variant; confirm current availability with the seller.</p><div id="ev-grid" class="ev-grid">'+''.join(card(v) for v in models)+'</div><div id="ev-empty" class="ev-empty" hidden><h2>No matching vehicles</h2><p>Try another model, brand or category.</p></div><section id="ev-comparison" class="compare" aria-label="Vehicle comparison" hidden><div class="ev-compare-heading"><h2>Your comparison</h2><button id="ev-clear-compare" type="button">Clear comparison</button></div><p class="micro">Compare up to three models. Test cycles and variants can differ.</p><div id="ev-compare-table"></div></section><p id="ev-compare-message" role="status" class="micro"></p><div class="info-line"><b>What is the on-road price?</b><span>Ask for an itemised quote for your exact variant and city, including battery ownership, insurance and registration.</span>'+link('#price','Build a price estimate →')+'</div></section>'
(dist/'explore-evs/index.html').write_text(shell('Explore Electric Vehicles','Browse electric cars, scooters and motorcycles with real model galleries and source-linked specifications.',intro+price+running_widget()+schemes,'<script src="/catalogue-data.js"></script><script src="/catalogue.js"></script><script src="/calculations.js?v=6"></script><script src="/road-rules.js?v=6"></script><script src="/calculators.js?v=6"></script>'))
for v in models:
 url='/explore-evs/'+v['slug']+'/'
 name=v['brand']+' '+v['name'];imgs=v['images'];first=imgs[0]
 body='<div class="breadcrumbs">'+link('/','Home')+'<span>/</span>'+link('/explore-evs/','Explore EVs')+'<span>/</span><span>'+e(name)+'</span></div><section class="model-page"><div class="model-title"><div><span class="eyebrow">'+e(type_name(v))+' · '+e(v.get('body',''))+'</span><h1>'+e(name)+'</h1></div>'+link('/explore-evs/','← Back to all EVs','model-back')+'</div><div class="model-top"><div class="model-gallery"><figure><button class="gallery-main-button" id="gallery-expand" type="button" aria-label="Open larger vehicle photo"><img id="gallery-main" src="'+e(first['path'])+'" alt="'+e(first['alt'])+'" width="1200" height="800"><span class="gallery-expand-label">View larger ↗</span></button><figcaption id="gallery-caption">'+e(first['alt'])+'</figcaption></figure><div class="gallery-controls"><button type="button" id="gallery-prev" aria-label="Previous photo">←</button><span id="gallery-count" role="status">1 / '+str(len(imgs))+'</span><button type="button" id="gallery-next" aria-label="Next photo">→</button></div><div class="gallery-thumbnails" aria-label="Choose a vehicle photo">'
 for i,img in enumerate(imgs):body+='<button type="button" data-photo="'+str(i)+'" aria-label="Show photo '+str(i+1)+': '+e(img['alt'])+'" aria-pressed="'+str(i==0).lower()+'"><img src="'+e(img['path'])+'" alt="" width="150" height="100" loading="lazy"></button>'
 body+='</div><p class="micro photo-note">Images of this model from the sources listed below. Colour, equipment and market specification may differ from the variant you choose.</p></div><aside class="model-summary"><span class="eyebrow">AT A GLANCE</span><h2>Get to know your next ride.</h2><p class="model-price">'+e(v['price'])+'</p><p class="micro">'+e(v.get('priceNote',''))+'</p>'+subsidy(v)+'<dl class="model-specs">'
 for key,val in [('Claimed range',v['range']),('Battery capacity',v['battery']),('Body style',v.get('body',type_name(v)))]:body+='<div><dt>'+e(key)+'</dt><dd>'+e(val)+'</dd></div>'
 body+='</dl><p class="micro">Source: '+e(v.get('sourceLabel','Manufacturer'))+'. Prices vary by location and battery ownership plan.</p><p class="micro">'+e(v.get('availabilityNote','Listed in the manufacturer’s India range. Confirm your chosen variant and delivery availability locally.'))+'</p>'+link(v['officialUrl'],'View model source ↗','button')+link('/explore-evs/#running-cost','Estimate running-cost savings →','model-secondary')+road_widget(v)+'</aside></div><nav class="model-section-nav" aria-label="Model sections">'+link('#highlights','Highlights')+link('#ownership','Before you buy')+link('#sources','Sources & photos')+'</nav><section id="highlights" class="model-details"><div><span class="eyebrow">WHAT STANDS OUT</span><h2>Features for the way you move.</h2></div><div class="model-benefits">'
 for i,b in enumerate(v.get('benefits',[])):body+='<article><span>0'+str(i+1)+'</span><p>'+e(b)+'</p></article>'
 body+='</div></section>'+variant_table(v)+'<section id="ownership" class="model-details ownership-details"><div><span class="eyebrow">A CLOSER LOOK</span><h2>Good to know<br>before you decide.</h2></div><div class="model-facts">'+''.join('<p>'+e(f)+'</p>' for f in v.get('facts',[]))+'<details><summary>Plan your charging</summary><p>Check parking access, the required charger, installation costs and the charging options along your usual routes. Use the manufacturer’s charging guidance for this model.</p></details><details><summary>Compare the exact variant</summary><p>Confirm battery size, test-cycle range, warranty terms, local service coverage and what is included in the written quote. A starting price and the longest claimed range can refer to different variants.</p></details>'+link('/explore-evs/#schemes','Explore EV government support →')+'</div></section><section id="sources" class="model-sources"><span class="eyebrow">SOURCES & PHOTO CREDITS</span><p>Model information checked 14 October 2026. Specifications and photo credits link to the named model sources.</p><ul>'
 sources=list(dict.fromkeys([v['officialUrl']]+[x if isinstance(x,str) else x.get('url','') for x in v.get('sources',[])]))
 for i,u in enumerate(sources):
  if u:body+='<li>'+link(u,('Model specifications' if i==0 else 'Additional model information')+' ↗')+'</li>'
 body+='</ul><details><summary>Photo sources ('+str(len(imgs))+')</summary><ol>'
 for img in imgs:body+='<li>'+link(img.get('sourceUrl') or img.get('url'),e(img['alt'])+' ↗')+'</li>'
 body+='</ol></details></section></section><dialog id="photo-dialog" class="photo-dialog"><div class="photo-dialog-toolbar"><span id="dialog-count"></span><button type="button" id="dialog-close" aria-label="Close photo gallery">Close ✕</button></div><img id="dialog-image" alt=""><div class="photo-dialog-controls"><button type="button" id="dialog-prev" aria-label="Previous photo">← Previous</button><span id="dialog-caption"></span><button type="button" id="dialog-next" aria-label="Next photo">Next →</button></div></dialog>'
 path=dist/'explore-evs'/v['slug']/'index.html';path.parent.mkdir(parents=True,exist_ok=True)
 image_json=json.dumps([{'src':x['path'],'alt':x['alt']} for x in imgs],ensure_ascii=False).replace('<','\\u003c')
 path.write_text(shell(name,name+' photos, claimed range, battery, features and buying considerations.',body,'<script type="application/json" id="gallery-data">'+image_json+'</script><script src="/gallery.js"></script><script src="/calculations.js?v=6"></script><script src="/road-rules.js?v=6"></script><script src="/calculators.js?v=6"></script>'))
# The listing is server-rendered; only comparison needs the compact data payload.
compact=[{k:v[k] for k in ['slug','brand','name','type','range','battery','price','priceMin']} for v in models]
(dist/'catalogue-data.js').write_text('window.evCatalogue='+json.dumps(compact,ensure_ascii=False).replace('<','\\u003c')+';')
print('Built',len(models),'model pages with',sum(len(v['images']) for v in models),'photos')
